{"requirements": {"postgresql:diagnose-order-query": {"skill_id": "postgresql", "description": "Chẩn đoán và tối ưu truy vấn PostgreSQL lọc và sắp xếp danh sách đơn hàng trên bảng lớn.", "required_proficiency": 4.0, "inferred": false, "requirement_kind": "REQUIRED", "jd_evidence_spans": ["Bắt buộc: Chẩn đoán và tối ưu truy vấn PostgreSQL lọc và sắp xếp danh sách đơn hàng trên bảng lớn."]}, "python:deduplicate-events": {"skill_id": "python", "description": "Viết hàm Python loại trùng sự kiện đơn hàng theo mã sự kiện, giữ nguyên thứ tự xuất hiện đầu tiên.", "required_proficiency": 3.5, "inferred": true, "requirement_kind": "REQUIRED", "jd_evidence_spans": ["Bắt buộc: Viết hàm Python loại trùng sự kiện đơn hàng theo mã sự kiện, giữ nguyên thứ tự xuất hiện đầu tiên."]}, "rabbitmq:design-payment-consumer": {"skill_id": "rabbitmq", "description": "Thiết kế consumer RabbitMQ cho sự kiện thanh toán để việc giao lại thông điệp không ghi nhận thanh toán hai lần.", "required_proficiency": 4.0, "inferred": false, "requirement_kind": "REQUIRED", "jd_evidence_spans": ["Bắt buộc: Thiết kế consumer RabbitMQ cho sự kiện thanh toán để việc giao lại thông điệp không ghi nhận thanh toán hai lần."]}}, "depth_definitions": {"1": "Foundation: recognize, define and explain fundamental concepts", "2": "Application: independently apply a concept to a concrete bounded task", "3": "Analysis & Problem Solving: investigate causes, debug and reason through alternatives", "4": "Design & Trade-offs: design a solution, evaluate constraints and technical trade-offs"}, "allow_extension_probes": false}

Respond with a JSON object in the following order of fields: `blueprint` (must be formatted as a valid Python BlueprintDraft).

{
  "blueprint": {
    "objectives": [
      {
        "requirement_id": "http-api:explain-http-retry",
        "skill_id": "http-api",
        "criteria": [
          {
            "description": "Định nghĩa chính xác tính idempotent trong ngữ cảnh HTTP và phân biệt với các phương thức khác (POST, PUT, PATCH).",
            "expected_evidence": "Ứng viên giải thích rằng một yêu cầu được thực hiện nhiều lần phải tạo ra cùng kết quả như khi thực hiện một lần. Ví dụ: PUT /orders/{id} là idempotent, POST /orders không phải.",
            "below_target": "Không thể định nghĩa idempotent hoặc nhầm lẫn với 'an toàn' (safe) của GET. Không nhận ra rủi ro khi retry POST.",
            "at_target": "Giải thích đúng khái niệm idempotent. Nhận ra rằng retry một request đã gửi nhưng chưa nhận được phản hồi (timeout) có thể dẫn đến trùng lặp nếu phương thức không idempotent (ví dụ: POST). Đề xuất sử dụng PUT hoặc thêm IDempotency-Key header cho POST.",
            "above_target": "Phân tích sâu hơn về cơ chế retry ở tầng mạng vs ứng dụng. Thảo luận về việc xử lý race conditions khi client retry đồng thời với server đang xử lý request gốc, và cách thiết kế API để đảm bảo tính nhất quán cuối cùng (eventual consistency) nếu idempotency không khả thi."
          },
          {
            "description": "Áp dụng kiến thức về idempotent để đề xuất chiến lược retry an toàn cho trường hợp timeout cập nhật đơn hàng.",
            "expected_evidence": "Đề xuất chuyển đổi từ POST sang PUT nếu có thể, hoặc sử dụng cơ chế kiểm tra trạng thái trước khi retry. Giải thích tại sao retry tự động trên POST nguy hiểm.",
            "below_target": "Khuyến nghị retry liên tục mà không quan tâm đến phương thức HTTP hoặc trạng thái đơn hàng. Không nhận ra rủi ro double-charge hoặc duplicate order.",
            "at_target": "Nhận diện rủi ro double-order khi retry POST sau timeout. Đề xuất: 1) Sử dụng PUT nếu API hỗ trợ. 2) Nếu chỉ dùng POST, cần cơ chế client-side tracking (request ID) để tránh gửi lại. 3) Kiểm tra trạng thái đơn hàng trước khi retry nếu có thể.",
            "above_target": "Thiết kế giải pháp bao gồm việc triển khai Idempotency Key header tiêu chuẩn. Thảo luận về trade-off giữa độ phức tạp của client và sự an toàn của data. Đề xuất cơ chế compensation transaction (SAGA) nếu hệ thống phân tán."
          }
        ],
        "suitable_modes": [
          {
            "mode": "TECHNICAL_EXPLANATION",
            "criterion_indices": [0, 1]
          }
        ],
        "target_depth": 3,
        "depth_basis": "Analysis & Problem Solving",
        "depth_evidence_spans": [
          "Bắt buộc: Giải thích tính idempotent của HTTP khi retry yêu cầu cập nhật đơn hàng sau timeout."
        ],
        "depth_rationale": "Yêu cầu đòi hỏi phải điều tra nguyên nhân (timeout), debug rủi ro (double order), và suy luận qua các lựa chọn thay thế (PUT vs POST + key). Đây là mức độ phân tích và giải quyết vấn đề, vượt xa việc chỉ nhớ định nghĩa (L1) hay áp dụng đơn thuần (L2)."
      },
      {
        "requirement_id": "incident-collaboration:coordinate-mitigation",
        "skill_id": "incident-collaboration",
        "criteria": [
          {
            "description": "Xác định vai trò và trách nhiệm cụ thể của Dev, QA và SRE trong giai đoạn giảm thiểu tác động (mitigation) của sự cố đơn hàng.",
            "expected_evidence": "Liệt kê rõ ràng: SRE giám sát metrics và rollback/fix infra; QA xác minh regression và test hotfix; Dev viết code fix và review. Nhấn mạnh sự phối hợp đồng bộ.",
            "below_target": "Không rõ vai trò của từng bên. Cho rằng Dev làm tất cả hoặc QA chịu trách nhiệm kỹ thuật. Không biết ai là người ra lệnh stop-the-line.",
            "at_target": "Phân công rõ ràng: SRE chịu trách nhiệm ổn định hệ thống (rollback, traffic shifting), QA chịu trách nhiệm chất lượng hotfix, Dev chịu trách nhiệm sửa lỗi code. Đề xuất kênh giao tiếp chung (chat room/incident channel).",
            "above_target": "Thảo luận về cơ chế ra quyết định nhanh (commander model) trong sự cố nghiêm trọng. Đề xuất quy trình handoff rõ ràng từ mitigation sang post-mortem. Phân tích điểm nghẽn trong giao tiếp đa đội nhóm."
          },
          {
            "description": "Thực hiện quy trình bàn giao theo dõi (handover) sau khi sự cố được khắc phục tạm thời.",
            "expected_evidence": "Tạo ticket/post-mortem draft, liệt kê root cause hypothesis, các bước đã làm, và các metric cần theo dõi tiếp. Đảm bảo thông tin được chuyển giao đầy đủ cho team trực ca tiếp theo hoặc team phân tích.",
            "below_target": "Kết thúc cuộc gọi/chat mà không ghi chép lại. Không nói rõ những gì cần làm tiếp theo. Thông tin bị thất lạc giữa các đội.",
            "at_target": "Tổng kết ngắn gọn các hành động đã thực hiện. Bàn giao danh sách các triệu chứng còn lại cần theo dõi. Chỉ định người phụ trách chính cho mỗi task tiếp theo. Ghi lại vào incident log.",
            "above_target": "Đề xuất cải tiến quy trình dựa trên sự cố này (blameless post-mortem inputs). Phân tích hiệu quả của quá trình handover và đề xuất automation cho việc capture logs/metrics trong tương lai để giảm tải thủ công."
          }
        ],
        "suitable_modes": [
          {
            "mode": "BEHAVIORAL",
            "criterion_indices": [0, 1]
          }
        ],
        "target_depth": 3,
        "depth_basis": "Analysis & Problem Solving",
        "depth_evidence_spans": [
          "Bắt buộc: Phối hợp với QA và SRE để thống nhất giảm thiểu tác động và bàn giao theo dõi trong sự cố đơn hàng."
        ],
        "depth_rationale": "Yêu cầu đòi hỏi phải điều phối các bên liên quan, giải quyết xung đột tiềm tàng về trách nhiệm, và đưa ra quyết định trong tình huống áp lực (sự cố). Cần khả năng phân tích vai trò và giải quyết vấn đề phối hợp, không chỉ là tuân thủ quy trình (L2)."
      },
      {
        "requirement_id": "docker:write-dev-container",
        "skill_id": "docker",
        "criteria": [
          {
            "description": "Viết Dockerfile tối giản cho API nội bộ, tập trung vào môi trường phát triển.",
            "expected_evidence": "Sử dụng multi-stage build hoặc image base nhẹ (alpine/distroless). Chỉ cài đặt dependencies cần thiết cho dev (debugger, linter). Không copy source code production vào image dev nếu không cần thiết.",
            "below_target": "Sử dụng image base lớn (ubuntu full) không cần thiết. Copy toàn bộ project bao gồm node_modules/.git. Không tận dụng cache layer của Docker.",
            "at_target": "Chọn image base phù hợp (ví dụ: python:3.9-slim). Copy chỉ file requirements.txt trước để tận dụng cache. Copy source code sau. Thêm volume mount cho code để live reload. Loại bỏ artifacts không cần thiết.",
            "above_target": "Tối ưu hóa kích thước image bằng distroless hoặc scratch nếu có thể. Cấu hình user không phải root để bảo mật. Thiết lập healthcheck cơ bản. Thảo luận về trade-off giữa tốc độ build và kích thước image."
          }
        ],
        "suitable_modes": [
          {
            "mode": "CODING",
            "criterion_indices": [0]
          }
        ],
        "target_depth": 2,
        "depth_basis": "Application",
        "depth_evidence_spans": [
          "Điểm cộng: Viết Dockerfile tối giản cho API nội bộ dùng trong môi trường phát triển."
        ],
        "depth_rationale": "Yêu cầu là viết một Dockerfile cụ thể cho một mục đích rõ ràng (dev environment). Đây là nhiệm vụ áp dụng kiến thức Docker vào một task giới hạn, không yêu cầu phân tích phức tạp hay thiết kế hệ thống phân tán. Do đó, L2 là phù hợp nhất."
      }
    ]
  }
}

{
  "blueprint": {
    "objectives": [
      {
        "requirement_id": "postgresql:diagnose-order-query",
        "skill_id": "postgresql",
        "criteria": [
          {
            "description": "Xác định và giải thích các vấn đề hiệu năng trong truy vấn lọc/sắp xếp đơn hàng (ví dụ: thiếu index, full table scan).",
            "expected_evidence": "Candidate phân tích `EXPLAIN ANALYZE`, chỉ ra điểm nghẽn (bottleneck) và đề xuất thêm index hoặc điều chỉnh query.",
            "below_target": "Không nhận diện được vấn đề hiệu năng hoặc đề xuất sai lệch cơ bản (ví dụ: xóa toàn bộ dữ liệu).",
            "at_target": "Nhận diện đúng vấn đề (ví dụ: cần index trên cột status/created_at), giải thích lý do bằng EXPLAIN, và đưa ra câu lệnh ALTER TABLE ADD INDEX hoặc tối ưu WHERE clause phù hợp.",
            "above_target": "Đề xuất giải pháp đa chiều như partial index, covering index, hoặc phân tích trade-off giữa chi phí ghi (write overhead) và đọc (read performance) trên bảng lớn."
          },
          {
            "description": "Thực thi thay đổi schema hoặc query để cải thiện hiệu suất mà không làm thay đổi logic nghiệp vụ.",
            "expected_evidence": "Candidate viết chính xác câu lệnh SQL tạo index hoặc sửa query, đảm bảo kết quả trả về vẫn đúng theo yêu cầu ban đầu.",
            "below_target": "Viết sai cú pháp SQL hoặc thay đổi logic truy vấn dẫn đến kết quả sai.",
            "at_target": "Viết đúng cú pháp tạo index hoặc tối ưu query, giữ nguyên thứ tự sắp xếp và điều kiện lọc.",
            "above_target": "Xem xét tác động của index mới lên các truy vấn khác (query plan regression) và đề xuất chiến lược kiểm thử hoặc rollback nếu cần."
          }
        ],
        "suitable_modes": [
          {
            "mode": "DEBUGGING"
          },
          {
            "mode": "TECHNICAL_EXPLANATION"
          }
        ],
        "target_depth": 3,
        "depth_basis": "ANALYSIS_PROBLEM_SOLVING",
        "depth_evidence_spans": [
          "Chẩn đoán và tối ưu truy vấn PostgreSQL lọc và sắp xếp danh sách đơn hàng trên bảng lớn."
        ],
        "depth_rationale": "Yêu cầu đòi hỏi khả năng điều tra nguyên nhân gốc rễ (chẩn đoán) và suy luận qua các lựa chọn thay thế để tối ưu hóa, vượt quá việc áp dụng đơn thuần (L2) nhưng chưa yêu cầu thiết kế hệ thống phức tạp (L4)."
      },
      {
        "requirement_id": "python:deduplicate-events",
        "skill_id": "python",
        "criteria": [
          {
            "description": "Triển khai thuật toán loại bỏ phần tử trùng lặp dựa trên mã sự kiện, duy trì thứ tự xuất hiện đầu tiên.",
            "expected_evidence": "Candidate viết hàm Python sử dụng cấu trúc dữ liệu phù hợp (như dict/set để tracking) để đạt độ phức tạp thời gian O(n) hoặc gần đó, thay vì dùng nested loop O(n^2).",
            "below_target": "Sử dụng phương pháp vét cạn (nested loops) gây chậm với dữ liệu lớn, hoặc không giữ được thứ tự ban đầu.",
            "at_target": "Sử dụng dictionary hoặc set để theo dõi các ID đã thấy, duyệt qua list một lần, thêm vào kết quả nếu chưa gặp. Kết quả có thứ tự đúng.",
            "above_target": "Xử lý các trường hợp edge case như sự kiện là object phức tạp (cần hashable key), hoặc tối ưu bộ nhớ khi xử lý stream dữ liệu khổng lồ (generator-based approach)."
          },
          {
            "description": "Đảm bảo tính đúng đắn của hàm với các đầu vào rỗng, null, hoặc dữ liệu không đồng nhất.",
            "expected_evidence": "Candidate kiểm tra input validation hoặc xử lý ngoại lệ gracefully.",
            "below_target": "Hàm bị crash khi gặp input null hoặc empty list.",
            "at_target": "Hàm trả về list rỗng hoặc xử lý an toàn khi input không hợp lệ.",
            "above_target": "Thiết kế hàm pure, không side-effect, dễ dàng test unit và có type hinting rõ ràng."
          }
        ],
        "suitable_modes": [
          {
            "mode": "CODING"
          }
        ],
        "target_depth": 2,
        "depth_basis": "APPLICATION",
        "depth_evidence_spans": [
          "Viết hàm Python loại trùng sự kiện đơn hàng theo mã sự kiện, giữ nguyên thứ tự xuất hiện đầu tiên."
        ],
        "depth_rationale": "Đây là một nhiệm vụ lập trình cụ thể, bounded task yêu cầu áp dụng kiến thức cơ bản về cấu trúc dữ liệu và thuật toán để giải quyết vấn đề trực tiếp."
      },
      {
        "requirement_id": "rabbitmq:design-payment-consumer",
        "skill_id": "rabbitmq",
        "criteria": [
          {
            "description": "Thiết kế cơ chế xử lý tin nhắn (message handling) để đảm bảo tính toàn vẹn giao dịch (không thanh toán hai lần) khi có tin nhắn bị gửi lại (redelivery).",
            "expected_evidence": "Candidate mô tả cách sử dụng idempotency key (payment_id) hoặc trạng thái giao dịch trong database để phát hiện và bỏ qua tin nhắn trùng lặp.",
            "below_target": "Chỉ xử lý tin nhắn ngay lập tức mà không có cơ chế kiểm tra trùng lặp, dẫn đến rủi ro double-spending.",
            "at_target": "Kiểm tra xem payment_id đã tồn tại và thành công trong DB trước khi xử lý logic thanh toán. Nếu có, ack message và bỏ qua.",
            "above_target": "Thiết kế cơ chế retry với backoff, dead-letter queue (DLQ) cho các trường hợp lỗi không phục hồi, và đảm bảo transaction boundary rõ ràng giữa việc cập nhật trạng thái và ack message."
          },
          {
            "description": "Xác định cấu hình RabbitMQ phù hợp (acknowledgement, durability, prefetch) để hỗ trợ độ tin cậy cao.",
            "expected_evidence": "Candidate đề xuất channel.basic_ack sau khi xử lý thành công, và cấu hình queue durable/exchange durable.",
            "below_target": "Sử dụng auto-acknowledgement, dẫn đến mất tin nhắn nếu consumer crash giữa chừng.",
            "at_target": "Sử dụng manual acknowledgement, đảm bảo tin nhắn chỉ bị xóa khỏi queue sau khi xử lý xong và ghi nhận thành công.",
            "above_target": "Phân tích trade-off giữa throughput và độ tin cậy, đề xuất cấu hình prefetch count phù hợp để tránh memory overflow trên consumer."
          }
        ],
        "suitable_modes": [
          {
            "mode": "DESIGN"
          },
          {
            "mode": "TECHNICAL_EXPLANATION"
          }
        ],
        "target_depth": 4,
        "depth_basis": "DESIGN_TRADE_OFFS",
        "depth_evidence_spans": [
          "Thiết kế consumer RabbitMQ cho sự kiện thanh toán để việc giao lại thông điệp không ghi nhận thanh toán hai lần."
        ],
        "depth_rationale": "Yêu cầu liên quan đến thiết kế giải pháp cho một vấn đề phân tán phức tạp (idempotency, reliability), đòi hỏi đánh giá các ràng buộc hệ thống và trade-offs kỹ thuật."
      }
    ]
  }
